"""Generate legacy-compat fixtures (auth.json, schema.sql) with the ACTUAL old Python libs.

Historical generator: requires a checkout of the Python backend before its removal.
This file moved with the fixtures into apps/studio-api; it is not runnable against
current source, which no longer contains app.models or the old Python services.
To regenerate, use that historical checkout and direct /out to this directory.

Notes:
- Only `app.models.user` / `app.models.version` are imported (they pull `app.models.base`
  only), so no settings/vault/DB side effects occur and no env is required.
- Token creation mirrors app/modules/users/utils/auth.py (create_access_token /
  create_refresh_token: HS256, `type` claim, exp from an Asia/Ho_Chi_Minh-aware datetime)
  and app/modules/admin/services/auth_admin.py (admin: {"sub": "admin", "admin": True}),
  but the clock is frozen at CLOCK so tokens are deterministic given the secret.
  app.modules.users.utils.auth itself is not imported (it needs fastapi/settings/db).
- Password hashes use salts, so re-running yields different hashes (all still valid).
- /out is the output directory (auth.json, schema.sql).
"""
import json
import sys
from datetime import datetime, timedelta

import jwt
from passlib.context import CryptContext
from pytz import timezone
from sqlalchemy.dialects import postgresql
from sqlalchemy.schema import CreateIndex, CreateTable

sys.path.insert(0, "/repo")
from app.models.user import User  # noqa: E402
from app.models.version import Version  # noqa: E402

OUT = "/out"
PASSWORD = "LegacyPass1!"
SECRET = "legacy-test-secret-not-for-production"
CLOCK = 1792000000  # epoch seconds; fixed "now" used for exp computation
ACCESS_MINUTES = 11520  # settings.ACCESS_TOKEN_EXPIRE_MINUTES default
REFRESH_MINUTES = 43200  # settings.REFRESH_TOKEN_EXPIRE_MINUTES default
TZ = timezone("Asia/Ho_Chi_Minh")


def _now():
    return datetime.fromtimestamp(CLOCK, TZ)


def create_access_token(data, expires_delta=None):
    to_encode = data.copy()
    expire = _now() + (expires_delta or timedelta(minutes=ACCESS_MINUTES))
    to_encode.update({"exp": expire, "type": "access"})
    return jwt.encode(to_encode, SECRET, algorithm="HS256")


def create_refresh_token(data, expires_delta=None):
    to_encode = data.copy()
    expire = _now() + (expires_delta or timedelta(minutes=REFRESH_MINUTES))
    to_encode.update({"exp": expire, "type": "refresh"})
    return jwt.encode(to_encode, SECRET, algorithm="HS256")


pwd_context = CryptContext(schemes=["argon2", "bcrypt"], deprecated="auto")
argon2_hash = pwd_context.hash(PASSWORD)  # default scheme: argon2
bcrypt_hash = pwd_context.hash(PASSWORD, scheme="bcrypt")
assert argon2_hash.startswith("$argon2") and bcrypt_hash.startswith("$2")
assert pwd_context.verify(PASSWORD, argon2_hash) and pwd_context.verify(PASSWORD, bcrypt_hash)

user_data = {"sub": "7"}
fixture = {
    "password": PASSWORD,
    "secret": SECRET,
    "clock": CLOCK,
    "access_ttl_minutes": ACCESS_MINUTES,
    "refresh_ttl_minutes": REFRESH_MINUTES,
    "argon2_hash": argon2_hash,
    "bcrypt_hash": bcrypt_hash,
    "access_token": create_access_token(user_data, timedelta(minutes=ACCESS_MINUTES)),
    "refresh_token": create_refresh_token(user_data, timedelta(minutes=REFRESH_MINUTES)),
    "admin_access_token": create_access_token(
        {"sub": "admin", "admin": True}, timedelta(minutes=ACCESS_MINUTES)
    ),
}
with open(f"{OUT}/auth.json", "w") as f:
    json.dump(fixture, f, indent=2)
    f.write("\n")

dialect = postgresql.dialect()
parts = []
for model in (User, Version):
    table = model.__table__
    parts.append(str(CreateTable(table).compile(dialect=dialect)).strip() + ";")
    for index in sorted(table.indexes, key=lambda i: i.name or ""):
        parts.append(str(CreateIndex(index).compile(dialect=dialect)).strip() + ";")
with open(f"{OUT}/schema.sql", "w") as f:
    f.write("-- Generated by generate.py from app/models/{user,version}.py (SQLAlchemy CreateTable, postgresql dialect).\n")
    f.write("\n\n".join(parts) + "\n")
print("ok")
